function addTours(base, records) {
  for (const line of records.split("\n")) {
    const [id, mls] = line.split(" ");
    tours.set(id, base + mls);
  }
}

export function hasListingTour(id) {
  return tours.has(id);
}

export function attachListingTour(panel, row) {
  const spanish = document.documentElement?.lang === "es";
  const url = tours.get(row.id);
  if (!url) return;

  const section = document.createElement("details");
  section.className = "listing-photo-tour";
  const toggle = document.createElement("summary");
  toggle.textContent = spanish ? "Recorrido fotográfico" : "Listing photo tour";
  const provider = document.createElement("p");
  const source = document.createElement("a");
  source.href = url;
  source.target = "_blank";
  source.rel = "noopener noreferrer";
  source.textContent = "Property Panorama";
  provider.append(source, " · MLS " + url.split("/").pop());

  const note = document.createElement("small");
  note.textContent = spanish ? "Fotos de la publicación. La fecha y las vistas varían." : "Listing photos. Dates and views vary by property.";
  provider.append(document.createElement("br"), note);
  section.append(toggle, provider);
  section.addEventListener("toggle", () => {
    if (!section.open) {
      section.querySelector("iframe")?.remove();
      return;
    }
    if (section.querySelector("iframe")) return;
    const frame = document.createElement("iframe");
    frame.title = (spanish ? "Recorrido fotográfico de " : "Listing photo tour of ") + row.address;
    frame.src = url;
    frame.allowFullscreen = true;
    frame.referrerPolicy = "strict-origin-when-cross-origin";
    section.append(frame);
  });
  panel.prepend(section);
  section.open = true;
}
